//! Authored cache/budget admission cases, no provider or semantic gold.
use lightog_core::{common::{canonical_hash,text_sha},source_answer_budget_v1::{execute,VERSION}};
use serde_json::{json,Value};
fn fixture(documents:usize)->Value {let binding=json!({"role":"embedding","model":"authored","config_revision":1,"model_revision":"v1","dimensions":2,"binding_origin":"HOST_CURRENT_CONFIGURATION_NOT_REMOTE_AUTHENTICATION"});let scope=json!({"version":"lightog-source-product-budget/1","input":{"sources":[]},"context":{"operation":"ASK","question":"Which source statement?"},"source_stamp":{"base_id":"authored","source_epoch":1},"snapshot":{"base_ref":"authored","source_epoch":1,"graph_revision":"g1","sources":[]},"models":{"generation":null,"embedding":binding,"reranker":null}});let docs=(0..documents).map(|n|text_sha(&format!("authored document {n}"))).collect::<Vec<_>>();let query=text_sha("Which source statement?");let rows=docs.iter().map(|d|("document",d)).chain(std::iter::once(("query",&query))).map(|(kind,digest)|json!({"cache_id":canonical_hash(&json!({"binding":binding,"input_type":kind,"text_sha256":digest})),"cache":null,"pending":null})).collect::<Vec<_>>();json!({"contract_version":VERSION,"scope":scope,"document_text_sha256s":docs,"query_text_sha256s":[query],"cache_observations":rows,"budget":{"status":"AUTHORIZED","scope_sha256":canonical_hash(&scope),"limits":{"embedding":10},"used":{"embedding":0}}})}
fn cache(p:&mut Value,n:usize){let kind=if n<p["document_text_sha256s"].as_array().unwrap().len(){"document"}else{"query"};let digest=if kind=="document"{p["document_text_sha256s"][n].clone()}else{p["query_text_sha256s"][0].clone()};p["cache_observations"][n]["cache"]=json!({"id":p["cache_observations"][n]["cache_id"],"binding":p["scope"]["models"]["embedding"],"input_type":kind,"text_sha256":digest,"values":[1.0,0.5],"completed_attempt_id":"authored_returned_attempt"});}
#[test]fn no_cache_both_lanes_count_separately_and_deduplicate(){let mut p=fixture(21);let d=p["document_text_sha256s"][0].clone();p["document_text_sha256s"].as_array_mut().unwrap().push(d);let r=execute("plan",&p).unwrap();assert_eq!(r["document_batches"],2);assert_eq!(r["query_batches"],1);assert_eq!(r["required_embedding_batches"],3);assert_eq!(r["document_unique_texts"],21);assert_eq!(r["generation_and_reranker_budget_guaranteed"],false);}
#[test]fn partial_and_complete_cache_use_actual_remaining_not_limits(){let mut p=fixture(21);cache(&mut p,0);p["budget"]["limits"]["embedding"]=json!(5);p["budget"]["used"]["embedding"]=json!(3);let r=execute("validate",&p).unwrap();assert_eq!(r["required_embedding_batches"],2);assert_eq!(r["embedding_remaining"],2);for n in 0..22 {cache(&mut p,n);}p["budget"]["used"]["embedding"]=json!(5);assert_eq!(execute("validate",&p).unwrap()["required_embedding_batches"],0);}
#[test]fn insufficient_total_rejected_before_any_document_batch(){let mut p=fixture(1);p["budget"]["limits"]["embedding"]=json!(1);assert_eq!(execute("validate",&p).unwrap_err().code,"SOURCE_EMBEDDING_BUDGET_INSUFFICIENT_PREFLIGHT");}
#[test]fn unknown_query_blocks_even_when_document_is_ready_and_confirm_override_ignored(){let mut p=fixture(1);cache(&mut p,0);p["cache_observations"][1]["pending"]=json!({"status":"UNKNOWN_NO_AUTOMATIC_RESEND"});p["confirmUnknownResend"]=json!(true);assert_eq!(execute("plan",&p).unwrap()["status"],"BLOCKED_UNKNOWN");assert_eq!(execute("validate",&p).unwrap_err().code,"SOURCE_EMBEDDING_OUTCOME_UNKNOWN_CONFIRMATION_REQUIRED");}
#[test]fn cache_model_drift_bad_vector_and_budget_scope_fail_closed(){let p=fixture(1);let mut cached=p.clone();cache(&mut cached,0);cached["cache_observations"][0]["cache"]["values"]=json!([0.0,0.0]);assert_eq!(execute("plan",&cached).unwrap_err().code,"SOURCE_VECTOR_CACHE_CHANGED");let mut drift=p.clone();drift["scope"]["models"]["embedding"]["config_revision"]=json!(2);assert_eq!(execute("plan",&drift).unwrap_err().code,"SOURCE_EMBEDDING_PLAN_CACHE_OBSERVATIONS_INVALID");let mut scope=p.clone();scope["budget"]["scope_sha256"]=json!("old");assert_eq!(execute("validate",&scope).unwrap_err().code,"SOURCE_BUDGET_SCOPE_CHANGED");}
#[test]fn observation_omission_and_query_substitution_cannot_reduce_cost(){let mut p=fixture(1);p["cache_observations"].as_array_mut().unwrap().pop();assert_eq!(execute("plan",&p).unwrap_err().code,"SOURCE_EMBEDDING_PLAN_CACHE_OBSERVATIONS_INVALID");let mut p=fixture(1);p["query_text_sha256s"]=json!([text_sha("another query")]);assert_eq!(execute("plan",&p).unwrap_err().code,"SOURCE_EMBEDDING_PLAN_QUERY_BINDING_INVALID");}
